CREATE TABLE IF NOT EXISTS models (
  slug TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  developer TEXT NOT NULL,
  release_date DATE,
  access TEXT NOT NULL CHECK (access IN ('proprietary', 'restricted', 'open_weights', 'open_source')),
  comparison_data JSONB NOT NULL DEFAULT '{}'::jsonb,
  sources JSONB NOT NULL DEFAULT '[]'::jsonb,
  notes TEXT,
  verified_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS models_release_date_idx ON models (release_date DESC, developer, name);

INSERT INTO models (slug, name, developer, release_date, access, comparison_data, sources, notes, verified_at)
SELECT
  seed.slug,
  seed.name,
  seed.developer,
  seed.release_date::date,
  seed.access,
  seed.comparison_data,
  seed.sources,
  seed.notes,
  NOW()
FROM jsonb_to_recordset($models$
